import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Syrolands Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),s={name:"guide/index.md"};function n(o,a,l,d,c,h){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="syrolands-guide" tabindex="-1">Syrolands Guide <a class="header-anchor" href="#syrolands-guide" aria-label="Permalink to &quot;Syrolands Guide&quot;">​</a></h1><p>A concise introduction to Syrolands for friends, testers and future players. The Lab contains accepted ideas, experiments and proposals; a system described here is not necessarily available to play.</p><h2 id="characters" tabindex="-1">Characters <a class="header-anchor" href="#characters" aria-label="Permalink to &quot;Characters&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/characters/progression.html">Character Progression</a> · <a href="/Syrolands-Public/guide/characters/skills.html">Skills, Skillcap &amp; Teachers</a> · <a href="/Syrolands-Public/guide/characters/techniques.html">Techniques &amp; Specializations</a> · <a href="/Syrolands-Public/guide/characters/character-creation.html">Character Creation &amp; Backgrounds</a> · <a href="/Syrolands-Public/guide/characters/stats.html">Stats Overview</a>.</p><p>These Proposed directions aim for useful early characters, meaningful specialization and responsive play; they are not confirmed live changes.</p><h2 id="combat" tabindex="-1">Combat <a class="header-anchor" href="#combat" aria-label="Permalink to &quot;Combat&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/combat/overview.html">Combat overview</a> explains automatic fighting, local injuries and the distinction between the current experiment and intended advanced interaction.</p><p><a href="/Syrolands-Public/guide/combat/limbs-and-trauma.html">Limbs and Trauma</a> · <a href="/Syrolands-Public/guide/combat/weapons-and-damage.html">Weapons and Damage Types</a> · <a href="/Syrolands-Public/guide/combat/armor-and-protection.html">Armor and Protection</a> · <a href="/Syrolands-Public/guide/combat/targeting-and-anatomy.html">Targeted Attacks and Anatomy</a> · <a href="/Syrolands-Public/guide/combat/stamina-and-reactive-combat.html">Stamina and Reactive Combat</a>.</p><h2 id="magic" tabindex="-1">Magic <a class="header-anchor" href="#magic" aria-label="Permalink to &quot;Magic&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/magic/overview.html">Magery overview</a> · <a href="/Syrolands-Public/guide/magic/learning-spells.html">Learning spells</a> · <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Spell Memory and Familiarity</a> · <a href="/Syrolands-Public/guide/magic/meditation-and-concentration.html">Meditation and Concentration</a> · <a href="/Syrolands-Public/guide/magic/spellbooks-scrolls-and-reagents.html">Spellbooks, scrolls and reagents</a> · <a href="/Syrolands-Public/guide/magic/variants-and-glyphs.html">Spell variants and glyphs</a>.</p><p>The Proposed magic model separates knowledge, execution, practice and preparation. These pages do not establish live gameplay.</p><h2 id="professions" tabindex="-1">Professions <a class="header-anchor" href="#professions" aria-label="Permalink to &quot;Professions&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/professions/overview.html">Professions overview</a> introduces the Proposed redesign: crafts as part of adventuring, learning, journals, production and reputation.</p><p><a href="/Syrolands-Public/guide/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/guide/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/guide/professions/inscription.html">Inscription</a>. Bowmaking is a technique path within Carpentry.</p><h2 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/items/item-quality.html">Item Quality / Masterworks</a> explains Proposed quality categories, materials, rare traits and item history.</p><h2 id="more-systems" tabindex="-1">More systems <a class="header-anchor" href="#more-systems" aria-label="Permalink to &quot;More systems&quot;">​</a></h2><p>Player guides will grow around World and Society / Economy as source material becomes ready. These categories do not imply empty pages or approved mechanics.</p><p>For existing detailed coverage, use the <a href="/Syrolands-Public/game-design/">Game Design index</a>.</p><h2 id="reading-feature-status" tabindex="-1">Reading feature status <a class="header-anchor" href="#reading-feature-status" aria-label="Permalink to &quot;Reading feature status&quot;">​</a></h2><p><strong>Proposed</strong> means a candidate idea; <strong>Accepted</strong> means approved intent. <strong>Experimental</strong> marks investigations and prototypes. <strong>Implemented</strong> identifies existing code with a stated scope. Availability and verification are listed separately: implemented does not promise a live or fully tested feature. These labels describe content, not a guarantee of current availability.</p>',21)])])}const p=e(s,[["render",n]]);export{u as __pageData,p as default};
